from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class RmodsSyncInfo(SchemaObject):
    dist_name = SchemaField(name='dist_name', optional=True)
    state = SchemaField(name='state', optional=True)

    def __init__(self, dist_name, state):
        self.dist_name = dist_name
        self.state = state

        super(RmodsSyncInfo, self).__init__()
